namespace sv_bd13af46a0114ce0bc85ed8314399dc7.Services;

/// <summary>
/// Scoped (per-circuit) service that tracks low-stock alert counts and
/// notifies all subscribed components when new data arrives.
/// </summary>
public sealed class InventoryAlertService
{
    private static readonly Random s_rng = new();

    private int _lastCount;

    public int LastKnownCount => _lastCount;

    /// <summary>Raised after a new alert count is fetched.</summary>
    public event Func<Task>? OnAlertCountChanged;

    /// <summary>Simulates a database query for low-stock items.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        int count;
        lock (s_rng)
        {
            count = s_rng.Next(0, 16);
        }
        return Task.FromResult(count);
    }

    /// <summary>
    /// Fetches a new count for the given warehouse, stores it,
    /// and broadcasts the change to all subscribers.
    /// </summary>
    public async Task RefreshAsync(string warehouseId)
    {
        _lastCount = await GetLowStockCountAsync(warehouseId);
        if (OnAlertCountChanged is not null)
            await OnAlertCountChanged.Invoke();
    }
}

