@page "/dashboard"
@rendermode InteractiveServer
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard – @WarehouseState.CurrentWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Current Site</h5>
        <p class="card-text fs-4">@WarehouseState.CurrentWarehouseName</p>
    </div>
</div>

<div class="card mb-4">
    <div class="card-body d-flex align-items-center gap-3">
        <h5 class="card-title mb-0">Low-Stock Alerts</h5>
        @if (_loading)
        {
            <div class="spinner-border spinner-border-sm" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        }
        else if (AlertService.LastKnownCount > 0)
        {
            <span class="badge bg-danger fs-5">@AlertService.LastKnownCount items below minimum</span>
        }
        else
        {
            <span class="badge bg-success fs-5">All stock levels OK</span>
        }
    </div>
    <div class="card-footer text-muted">
        Refreshes every 10 seconds &middot; Last checked: @_lastChecked?.ToString("T")
    </div>
</div>

@code {
    private CancellationTokenSource? _cts;
    private bool _loading = true;
    private DateTime? _lastChecked;

    protected override async Task OnInitializedAsync()
    {
        WarehouseState.OnChange += HandleWarehouseChange;
        AlertService.OnAlertCountChanged += HandleAlertChange;

        await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
        _lastChecked = DateTime.Now;
        _loading = false;

        _cts = new CancellationTokenSource();
        _ = PollAsync(_cts.Token);
    }

    private async Task PollAsync(CancellationToken ct)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        try
        {
            while (await timer.WaitForNextTickAsync(ct))
            {
                await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
                _lastChecked = DateTime.Now;
                await InvokeAsync(StateHasChanged);
            }
        }
        catch (OperationCanceledException) { }
    }

    private async Task HandleWarehouseChange()
    {
        _loading = true;
        await InvokeAsync(StateHasChanged);

        await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
        _lastChecked = DateTime.Now;
        _loading = false;
        await InvokeAsync(StateHasChanged);
    }

    private async Task HandleAlertChange()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        WarehouseState.OnChange -= HandleWarehouseChange;
        AlertService.OnAlertCountChanged -= HandleAlertChange;
    }
}

