using sv_bd13af46a0114ce0bc85ed8314399dc7.Services;

var builder = WebApplication.CreateBuilder(args);

// Add services to the container.
builder.Services.AddRazorComponents()
    .AddInteractiveServerComponents();

// Scoped = one instance per circuit (per browser tab), so each user
// gets independent warehouse selection and alert counts.
builder.Services.AddScoped<WarehouseStateService>();
builder.Services.AddScoped<InventoryAlertService>();

